function [dod, soc_min, soc, idx] = kpi_battery(soc, idx, ni)
%KPI_BATTERY  The battery over the window's samples idx[0..ni] of its state of charge soc: the depth of discharge [%] and the
%   lowest state of charge [%] (nan when the case states no power system).
%   length: 64
%   soc: inout real[1][*] (passed a plain number)
%   idx: inout int[*] (passed a whole number)
%   ni: int (passed a whole number)
%   returns dod: real[1] (passed a plain number)
%   returns soc_min: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    dod = 0;
    soc_min = 0;
    acc = NaN;
    for i = (0):((ni) - 1)
        acc = asils.models.kpistats.kpi_min(acc, soc((idx((i) + 1)) + 1));
    end
    dod = (100 * (1 - acc));
    soc_min = (100 * acc);
end
